<template><view class="media-video"><video :id="videoId" :src="media(src)" :poster="media(poster)" :loop="loop" :controls="started" :show-center-play-btn="false" :show-fullscreen-btn="true" object-fit="cover" @loadedmetadata="metadata" @play="started=true" @error="failed"/><view v-if="!started" class="cover" @click="play" role="button" aria-label="播放视频"><image :src="media(poster)" mode="aspectFill"/><view class="play"/><text v-if="duration" class="duration">{{duration}}</text></view></view></template>
<script setup>
import {ref,getCurrentInstance,onMounted,onBeforeUnmount} from 'vue';import {media} from '../lib/content';
const props=defineProps({src:String,poster:String,loop:Boolean});const started=ref(false),duration=ref('');const instance=getCurrentInstance();const videoId='film-'+instance.uid;
const pause=()=>uni.createVideoContext(videoId,instance.proxy).pause();onMounted(()=>uni.$on('crowlook:pause-media',pause));onBeforeUnmount(()=>uni.$off('crowlook:pause-media',pause));
const metadata=e=>{const seconds=Math.floor(e.detail.duration||0);duration.value=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0')};const play=()=>{started.value=true;uni.createVideoContext(videoId,instance.proxy).play()};const failed=()=>{if(started.value)uni.showToast({title:'视频暂时无法播放，点击重试',icon:'none'});started.value=false}
</script>
<style scoped>.media-video{width:100%;height:100%;position:relative}.media-video video,.cover{position:absolute;inset:0;width:100%;height:100%}.cover image{width:100%;height:100%;display:block}.play{position:absolute;left:50%;top:50%;transform:translate(-38%,-50%);width:0;height:0;border-top:43rpx solid transparent;border-bottom:43rpx solid transparent;border-left:78rpx solid #ffffffa8;filter:drop-shadow(0 0 2rpx #0002)}.duration{position:absolute;right:26rpx;bottom:29rpx;color:#ffffffb8;font-size:30rpx;text-shadow:0 1rpx 4rpx #0002}</style>
